return $input.all().map((item, index) => {
  let text = item.json.content?.[0]?.text || '';

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const parsed = JSON.parse(text);

  return {
    json: {
      page_number: index + 1,
      ...parsed,
    },
  };
});

const allItems = $input.all();
const output = [];

for (const item of allItems) {
  const input = item.json;

  const fullText = input.text || '';
  const totalPages = input.numpages || null;
  const fileName = input.fileName || item.binary?.data?.fileName || null;

  const markerRegex = /Grower Name & Address\s+Foreign Purchaser/g;
  const matches = [...fullText.matchAll(markerRegex)];

  if (matches.length === 0) {
    output.push({
      json: {
        file_name: fileName,
        error: 'No invoices found using the expected document marker',
      },
    });
    continue;
  }

  for (let index = 0; index < matches.length; index++) {
    const start = matches[index].index;
    const end = index + 1 < matches.length
      ? matches[index + 1].index
      : fullText.length;

    output.push({
      json: {
        file_name: fileName,
        page_number: index + 1,
        total_pages: totalPages,
        raw_invoice_text: fullText.slice(start, end).trim(),
      },
    });
  }
}

return output;
